const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function importReportHTML(error,filename,{interactive=false,revision=0,notice='',outcome=''}={}){
 const issues=error.issues?.length?error.issues:[{location:'Файл',message:error.message||'Не удалось прочитать файл.'}];
 return `<p class="dialog-description">Не удалось открыть «${escape(filename)}». Найдено причин: ${issues.length}.</p>${notice?`<p class="import-review-notice ${outcome==='failure'?'is-failure':'is-success'}" role="status">${escape(notice)}</p>`:''}${notice?`<p class="dialog-description">Осталось ошибок импорта: ${issues.length}.</p>`:''}<ol class="import-problems" aria-label="Причины отказа импорта">${issues.map((issue,index)=>`<li data-problem-key="${escape(JSON.stringify([issue.target?.key||issue.location,issue.code,issue.message]))}"><strong>${escape(issue.location)}</strong><p>${escape(issue.message)}</p>${interactive?`<div class="import-problem-actions"><button type="button" class="primary import-repair-button" data-action="import-repair" data-index="${index}" data-revision="${revision}">Исправить</button><button type="button" class="secondary import-clear-button" data-action="import-clear" data-index="${index}" data-revision="${revision}" ${issue.target?'':`disabled title="Не удалось определить вопрос или раунд"`}>Очистить</button><span>${issue.target?.kind==='question'?'Очистка удалит содержимое вопроса':issue.target?.kind==='round'?'Очистка удалит содержимое всех вопросов раунда':'Структура пака недоступна'}</span></div>`:''}</li>`).join('')}</ol><p class="dialog-description">Текущий черновик не заменён. ${interactive?'Исправляйте или очищайте проблемы по одной. После устранения всех ошибок появится кнопка «Открыть пак». Очистка оставляет пустые вопросы для заполнения; исходный файл не меняется.':'Проверьте исходный файл и повторите импорт.'}</p>`;
}

export function importReadyHTML(state,filename){
 const cleared=state.summary?.clearedQuestions||state.summary?.clearedRounds;
 return `<p class="dialog-description">«${escape(filename)}»</p><section class="import-review-notice is-success" role="status"><strong>Проблем импорта больше нет</strong><p>${escape(state.notice||'Пак проверен и готов к открытию.')}</p></section><p class="dialog-description import-ready-description">Проверка пройдена. Теперь можно открыть пак в редакторе.</p>${cleared?'<p class="dialog-description">Очищенные вопросы остались пустыми. Их нужно заполнить перед экспортом.</p>':''}<p class="dialog-description">Текущий черновик пока не заменён. Исходный файл не изменён.</p>`;
}
